def deserialize(cls, val):
    if isinstance(val, int):
        return val
    if "(" in val:
        # Process macro-like keycodes
        return cls.process_macro_keycode(val)
    if val in cls.qmk_id_to_keycode:
        return cls.qmk_id_to_keycode[val].code
    return 0

@classmethod
def process_macro_keycode(cls, val):
    # Extract the keycode from the macro-like string
    keycode = val.split("(")[0].strip()
    if keycode in cls.qmk_id_to_keycode:
        return cls.qmk_id_to_keycode[keycode].code
    return 0
